export interface GpsCoordinate {
  lat: number;
  lng: number;
}

export interface CfsGpsSlot {
  id: string;
  name: string;
  code: string;
  block: string;
  row: string;
  bay: string;
  zoneType: string;
  cycle?: string;
  status: 'occupied' | 'available' | 'reserved' | 'maintenance' | 'incoming';
  center: GpsCoordinate;
  polygon: GpsCoordinate[];
  truckNumber?: string;
  driverName?: string;
  driverPhone?: string;
  transporter?: string;
  containerNumber?: string;
  isoCode?: string;
  shippingLine?: string;
  cargoType?: 'Dry' | 'Reefer' | 'Hazardous' | 'Empty';
  temperature?: string;
  sealNumber?: string;
  grossWeightKg?: number;
  dwellTime?: string;
  entryTime?: string;
  assignedTask?: string;
  tierLevel?: number;
  maxTiers?: number;
  priority?: boolean;
}

